/**
 * Shader for the pulsing halo.
 *
 * ## The mathematical idea
 *
 * A gaussian core that breathes to the rhythm of an adjustable period, and
 * rings emitted at that same rhythm: each is a gaussian of the distance to
 * the centre, whose radius grows with its phase, which widens and pales as
 * it moves away. The rings spread evenly over the period, so that the
 * emission is steady, never in bursts.
 *
 * Distinct from the sonar, whose fronts are steep, follow the pointer and
 * leave a dark wake: here everything is soft, slow, and applied by bounded
 * mixing towards the hues.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the rings and the halo.
 * - `uColorC` — the core.
 * - `uX`, `uY` — position of the centre, as a fraction of the frame.
 * - `uPeriod` — period of the rhythm, in seconds.
 * - `uRings` — number of rings in flight.
 * - `uSize` — reach of the rings, in frame heights.
 */
export const HALO_PULSE_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uX;
uniform float uY;
uniform float uPeriod;
uniform float uRings;
uniform float uSize;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  vec2 centre = vec2(uX * aspect, uY);
  float r = length(p - centre);

  float period = max(uPeriod, 0.5);
  float reach = max(uSize, 0.1);
  int n = int(clamp(uRings, 1.0, 6.0));

  // The rings: each offset by a fraction of the period, for a steady
  // emission. The radius grows with the phase; so does the width, and the
  // intensity falls as a square — a ring dies before its reach.
  float rings = 0.0;
  for (int i = 0; i < 6; i += 1) {
    if (i >= n) break;
    float phase = fract(uTime / period + float(i) / float(n));
    float radius = phase * reach;
    float width = 0.012 + 0.06 * phase;
    float e = (r - radius) / width;
    float life = 1.0 - phase;
    rings += exp(-e * e) * life * life;
  }

  // The core breathes to the same rhythm: it swells at emission.
  float breath = 0.5 + 0.5 * sin(uTime / period * 6.2831853);
  float core = exp(-r * r / (0.012 + 0.012 * breath));
  float halo = exp(-r * (7.0 - 2.5 * breath)) * 0.5;

  vec3 colour = mix(uColorA, uColorB, clamp(rings * 0.8 + halo * 0.6, 0.0, 1.0));
  colour = mix(colour, uColorC, clamp(core * (0.7 + 0.3 * breath), 0.0, 1.0));

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Pulsing halo: a core that breathes and rings emitted at a slow rhythm.
 *
 * ## The principle
 *
 * Gaussian rings whose radius grows with their phase, spread evenly over the
 * period for a steady emission; they widen and pale as they move away. The
 * core swells at every emission. Distinct from the sonar, with its steep
 * fronts and its pointer: here everything is soft and unhurried.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its fallback.
 * Reading the tokens, converting them to floats and re-reading them when the
 * theme changes all come from the engine.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface and under reduced
 * motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { HALO_PULSE_FRAGMENT } from './halo-pulse.shader.js'

/** What the escape hatch receives. */
export interface HaloPulseControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface HaloPulseOwnProps {
  /** Period of the rhythm, in milliseconds. @defaultValue 4000 */
  period?: number
  /** Number of rings in flight. @defaultValue 3 */
  rings?: number
  /** Reach of the rings, in frame heights. @defaultValue 0.8 */
  size?: number
  /** Horizontal position of the centre, as a fraction of the frame. @defaultValue 0.5 */
  x?: number
  /** Vertical position of the centre, as a fraction of the frame. @defaultValue 0.5 */
  y?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<HaloPulseControls>
}

/** Every property. */
export type HaloPulseProps = Customisable<HaloPulseOwnProps>

/** Tokens used by default: the background, the rings, the core. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-teal-400',
  '--o-palette-brand-500',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-br o-from-zinc-50 dark:o-from-zinc-950 o-to-teal-100 dark:o-to-teal-950'

/**
 * Pulsing halo.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <HaloPulse className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function HaloPulse({
  period = 4000,
  rings = 3,
  size = 0.8,
  x = 0.5,
  y = 0.5,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: HaloPulseProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: HALO_PULSE_FRAGMENT,
    colors,
    // The registry speaks in milliseconds, the shader in seconds.
    uniforms: { uPeriod: period / 1000, uRings: rings, uSize: size, uX: x, uY: y },
    name: 'halo-pulse',
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
